import{c as e,Q as r,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Anthropic 正式指控阿里巴巴 Qwen 透過 28M 次互動蒸餾 Claude（Bloomberg/CNBC/Reuters）","description":"","frontmatter":{"url":"https://x.com/dotey/status/2069979107903918149","title":"Anthropic 正式指控阿里巴巴 Qwen 透過 28M 次互動蒸餾 Claude（Bloomberg/CNBC/Reuters）","author":"dotey","archived":"2026-06-25T00:00:00.000Z","category":"anthropic-news","handle":"@dotey","published":"2026-06-25T00:00:00.000Z","score":5.65,"stats":"217❤ · 19 retweets","tags":["anthropic","alibaba","qwen","distillation-attack","lawsuit","export-control","bloomberg"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-06-25-@dotey-918149.md","filePath":"research/tweets/2026-06-25-@dotey-918149.md","lastUpdated":1785909234000}'),d={name:"research/tweets/2026-06-25-@dotey-918149.md"};function s(n,t,l,h,i,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="anthropic-正式指控阿里巴巴-qwen-透過-28m-次互動蒸餾-claude-—-dotey" tabindex="-1">Anthropic 正式指控阿里巴巴 Qwen 透過 28M 次互動蒸餾 Claude — @dotey <a class="header-anchor" href="#anthropic-正式指控阿里巴巴-qwen-透過-28m-次互動蒸餾-claude-—-dotey" aria-label="Permalink to &quot;Anthropic 正式指控阿里巴巴 Qwen 透過 28M 次互動蒸餾 Claude — @dotey&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/dotey/status/2069979107903918149" target="_blank" rel="noreferrer">https://x.com/dotey/status/2069979107903918149</a><strong>類別</strong>：anthropic-news <strong>統計</strong>：217❤ · 19 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Anthropic 今天正式致信美国参议院银行委员会和白宫，指控阿里巴巴旗下的通义千问（Qwen）AI 实验室对 Claude 发动了迄今为止规模最大的蒸馏攻击。</p><p>根据 CNBC 和 Reuters 获取的信件内容，通义千问关联方在 4 月 22 日到 6 月 5 日期间，通过大约 25,000 个虚假账号与 Claude 进行了超过 2880 万次交互。攻击的目标很明确：Claude 最核心的软件工程和 Agent 推理能力。</p><p>这个数字放到上下文里才知道有多夸张。今年 2 月，Anthropic 公开点名过 DeepSeek、MiniMax 和 Moonshot AI 三家，说它们用大约 24,000 个假账号总共产生了 1600 万次交互。阿里巴巴一家的量，接近之前三家加起来的两倍。</p><p>所谓蒸馏攻击（adversarial distillation），简单说就是拿别人家的顶级模型当老师，大规模喂它问题，收集回答，再用这些回答训练自己的模型。这样做的好处是可以跳过数百万甚至数十亿美元的独立研发成本，快速接近对手的能力水平。Claude 在中国是不可用的，所以这些操作本身就违反了 Anthropic 的服务条款。</p><p>更深的影响：这封信的出现时机非常微妙。它和 Fable 5 解禁谈判同步发生，这很可能是 Anthropic 向政府施压的一步棋——通过证明中国正在系统性盗窃其技术，来为 Fable 5 解禁谈判争取更有利的谈判条件，同时也在为&quot;为什么美国需要保持 AI 领先地位&quot;这个论点提供弹药。</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>4/10</td><td>信號但無直接行動；影響 API 使用成本認知和模型選擇長期思路</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>AI 蒸餾攻擊法律行動首例，規模前所未見</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>引用 CNBC + Reuters + Bloomberg 三方報導</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>詳細解釋蒸餾攻擊機制和規模量化</td></tr><tr><td>E. 泛化性 (15%)</td><td>5/10</td><td>地緣政治/法律事件為主</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.65/10</strong></td><td>4×0.3+7×0.2+7×0.2+6×0.15+5×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip（&lt; 6.0；重要消息但非技術深度；保留 tweets/ 歸檔作為 Anthropic 商業決策追蹤） <strong>理由</strong>：蒸餾攻擊規模是重大信號，但對 workspace 技術決策影響有限</p>',13)])])}const _=e(d,[["render",s]]);export{u as __pageData,_ as default};
